<script setup lang="ts">
import { computed } from 'vue'
import { formatDate } from './api'
import type { CatalogClassificationAssessment } from './discovery'
import { classificationComparisonLabels } from './classification-standards'
import ClassificationEvaluation from './ClassificationEvaluation.vue'
const props=defineProps<{assessment:CatalogClassificationAssessment}>()
const automatic=computed(()=>props.assessment.evaluation?{jobId:props.assessment.sourceId,runId:String(props.assessment.runId),observedAt:props.assessment.observedAt,classificationRevision:props.assessment.classificationRevision,comparison:props.assessment.comparison,comparisonReasons:props.assessment.reasons,evaluation:props.assessment.evaluation}:undefined)
const candidates=computed(()=>props.assessment.fields.filter(f=>f.sensitivity||f.hits?.length))
const labels:Record<string,string>={fresh_source_after_manual_confirmation_required:'人工确认后需重新领取任务并采集正向来源事实',manual_classification_confirmation_required:'需要人工确认分类，并取得确认后的新来源统计',current_positive_content_scope_required:'需要当前授权范围内可用的正向内容统计',adopted_standard_unavailable:'采用标准的自动规则不可用'}
</script>
<template><details class="catalog-assessment"><summary>目录评估 #{{assessment.id}} · {{classificationComparisonLabels[assessment.comparison]}} · 来源配置 v{{assessment.sourceRevision}}</summary><p>{{assessment.system}} · {{[assessment.database,assessment.schema,assessment.table].filter(Boolean).join(' / ')}}</p><p>来源 {{assessment.source}} #{{assessment.sourceId}} · 运行 #{{assessment.runId}} · 分类版本 {{assessment.classificationRevision}} · {{formatDate(assessment.observedAt)}}</p><p>此处展示采集时冻结的证据；能否当前复核由当前来源状态、人工分类、规则版本和整改周期共同决定。</p><ClassificationEvaluation v-if="automatic" :automatic="automatic" compact/><ul v-if="assessment.missingConditions.length"><li v-for="condition in assessment.missingConditions" :key="condition">{{labels[condition]||condition}}</li></ul><details><summary>客户规则与受限命中（{{candidates.length}} 个候选字段）</summary><ul><li v-for="rule in assessment.appliedRules" :key="rule.key">{{rule.key}} v{{rule.version}} · {{rule.name}} · {{rule.target}}</li></ul><ul><li v-for="field in candidates" :key="field.name"><strong>{{field.name}}</strong> · {{field.type}}<ul><li v-for="hit in field.hits" :key="hit.ruleKey+hit.ruleVersion+hit.method">{{hit.ruleKey}} v{{hit.ruleVersion}} · {{hit.category}} · {{hit.method}} · 命中 {{hit.matchCount}} / 已观察 {{hit.scannedCount}}</li></ul></li></ul></details><details><summary>采集覆盖与限制</summary><pre>{{JSON.stringify(assessment.coverage,null,2)}}</pre></details></details></template>
<style scoped>.catalog-assessment{margin:.8rem 0;padding:.8rem;border:1px solid var(--border,#ddd);border-radius:8px}.catalog-assessment p,.catalog-assessment li{font-size:.82rem;overflow-wrap:anywhere}.catalog-assessment pre{max-height:22rem;overflow:auto;white-space:pre-wrap}</style>
